-- PaStation menus: the coupon text now says dine-in and takeaway are both fine (content version 2). Only campaigns still at version 1
-- are touched; coupons already issued keep the text printed on them. A database created from the current content already has version 2.
begin;
update pci_private.discount_campaigns set version=2,translations=$json${"zh":{"name":"PaStation 豪华套餐 1 · €8 优惠券","conditions":"仅限豪华套餐 1，堂食、外带均可，需在午餐 12:00–13:00 或晚餐 15:00–22:30（意大利当地时间）使用。每张券核销一次。红酒和水二选一。有效期见券面。","menu":"豪华套餐 1","window":"午餐 12:00–13:00、晚餐 15:00–22:30（意大利当地时间）","list":"€27","pay":"€19"},"it":{"name":"PaStation Menù Deluxe 1 · coupon da 8 €","conditions":"Solo per il Menù Deluxe 1, da consumare al tavolo o da asporto, a pranzo dalle 12:00 alle 13:00 o a cena dalle 15:00 alle 22:30 (ora italiana). Una convalida per coupon. Vino rosso oppure acqua. La scadenza è sul coupon.","menu":"Menù Deluxe 1","window":"Pranzo 12:00–13:00 · Cena 15:00–22:30 · ora italiana","list":"27 €","pay":"19 €"},"en":{"name":"PaStation Deluxe Menu 1 · €8 coupon","conditions":"For Deluxe Menu 1 only, valid for eating in or takeaway, at lunch (12:00–13:00) or dinner (15:00–22:30), Italian local time. One redemption per coupon. Choose red wine or water. Expiry is shown on the coupon.","menu":"Deluxe Menu 1","window":"Lunch 12:00–13:00 · Dinner 15:00–22:30 · Italian local time","list":"€27","pay":"€19"}}$json$::jsonb where id='pastation-deluxe-1-8' and version=1;
update pci_private.discount_campaigns set version=2,translations=$json${"zh":{"name":"PaStation 豪华套餐 2 · €8 优惠券","conditions":"仅限豪华套餐 2，堂食、外带均可，需在午餐 12:00–13:00 或晚餐 15:00–22:30（意大利当地时间）使用。每张券核销一次。红酒和水二选一。有效期见券面。","menu":"豪华套餐 2","window":"午餐 12:00–13:00、晚餐 15:00–22:30（意大利当地时间）","list":"€27","pay":"€19"},"it":{"name":"PaStation Menù Deluxe 2 · coupon da 8 €","conditions":"Solo per il Menù Deluxe 2, da consumare al tavolo o da asporto, a pranzo dalle 12:00 alle 13:00 o a cena dalle 15:00 alle 22:30 (ora italiana). Una convalida per coupon. Vino rosso oppure acqua. La scadenza è sul coupon.","menu":"Menù Deluxe 2","window":"Pranzo 12:00–13:00 · Cena 15:00–22:30 · ora italiana","list":"27 €","pay":"19 €"},"en":{"name":"PaStation Deluxe Menu 2 · €8 coupon","conditions":"For Deluxe Menu 2 only, valid for eating in or takeaway, at lunch (12:00–13:00) or dinner (15:00–22:30), Italian local time. One redemption per coupon. Choose red wine or water. Expiry is shown on the coupon.","menu":"Deluxe Menu 2","window":"Lunch 12:00–13:00 · Dinner 15:00–22:30 · Italian local time","list":"€27","pay":"€19"}}$json$::jsonb where id='pastation-deluxe-2-8' and version=1;
commit;
